'use strict';

// Hosts that can only be a database on this machine. Anything else — a Railway
// proxy, a private IP, a Docker service name — is treated as shared.
const LOCAL_HOSTS = new Set(['localhost', '127.0.0.1', '::1', '[::1]']);

/**
 * True when a Postgres connection string points at a database on this machine.
 * Unparseable or missing URLs are NOT local: when in doubt, refuse.
 */
function isLocalDatabaseUrl(url) {
  if (!url) return false;
  try {
    const { protocol, hostname } = new URL(url);
    if (protocol !== 'postgresql:' && protocol !== 'postgres:') return false;
    return LOCAL_HOSTS.has(hostname.toLowerCase());
  } catch {
    return false;
  }
}

/**
 * The seed script wipes every user, location and report before inserting demo
 * data. Returns an error message when it must not run, or null when it may.
 */
function checkSeedAllowed(url, argv = []) {
  if (argv.includes('--force')) return null;
  if (isLocalDatabaseUrl(url)) return null;
  let host = '(unset)';
  try { host = new URL(url).hostname || host; } catch { if (url) host = '(unparseable)'; }
  return `Refusing to seed: DATABASE_URL host ${host} is not local. ` +
    'Seeding DELETES every user, location and report. ' +
    'If you really mean to wipe this database, run: npm run seed -- --force';
}

module.exports = { isLocalDatabaseUrl, checkSeedAllowed };

